      mat3(frame_info.model) * (rotation * morphed_tangent.xyz),
      mirrored ? -morphed_tangent.w : morphed_tangent.w);
  v_color = color * i_color;
  v_lightmap_uv = vec2(0.0);
  gl_Position = frame_info.mvp * local;
