  if (v_previous.w <= 0.0) {
    frag_color = vec4(0.0, 0.0, 0.0, 1.0);
    return;
  }
  frag_color = vec4(UvFromClip(v_current) - UvFromClip(v_previous), 0.0, 1.0);
}

